using System;using System.Collections.Generic;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class DungeonDecorationBuilder {
 const string Root="Assets/Resources/Decorations";static Material dark,metal,cyan,pink,violet,screen,vent,control,sign,glitch;static UnityEngine.SceneManagement.Scene preview;
 static Material Mat(string id,Color color,Texture texture=null,Rect? crop=null){string path=Root+"/Materials/"+id+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);bool create=m==null;if(create)m=new Material(Resources.Load<Shader>("Decorations/DecorationUnlit")){name=id,enableInstancing=true};m.SetColor("_BaseColor",color);if(texture!=null)m.SetTexture("_BaseMap",texture);if(crop.HasValue){var r=crop.Value;m.SetTextureScale("_BaseMap",new Vector2(r.width/texture.width,r.height/texture.height));m.SetTextureOffset("_BaseMap",new Vector2(r.x/texture.width,1-(r.y+r.height)/texture.height));}if(create)AssetDatabase.CreateAsset(m,path);else EditorUtility.SetDirty(m);return m;}
 static Transform Part(GameObject root,string name,Vector3 pos,Vector3 size,Material mat,PrimitiveType shape=PrimitiveType.Cube){var o=GameObject.CreatePrimitive(shape);o.name=name;o.transform.SetParent(root.transform,false);o.transform.localPosition=pos;o.transform.localScale=size;o.GetComponent<Renderer>().sharedMaterial=mat;UnityEngine.Object.DestroyImmediate(o.GetComponent<Collider>());return o.transform;}
 static Transform Face(GameObject root,Material mat,Vector3 pos,Vector2 size){var p=Part(root,"Dibujo frontal",pos,new Vector3(size.x,size.y,1),mat,PrimitiveType.Quad);p.localRotation=Quaternion.Euler(0,180,0);return p;}
 static void Panel(GameObject root,Material artwork,float y=1.5f,float w=1.4f,float h=1){Part(root,"Carcasa",new Vector3(0,y,.12f),new Vector3(w+.18f,h+.18f,.24f),dark);Part(root,"Borde cian",new Vector3(0,y,.25f),new Vector3(w+.06f,h+.06f,.025f),cyan);Face(root,artwork,new Vector3(0,y,.27f),new Vector2(w,h));}
 static DungeonDecorationDefinition Save(string id,string name,DecorationMount mount,Action<GameObject> create,DecorationTheme theme=DecorationTheme.General,float depth=.3f,bool corner=false){var root=new GameObject(name);UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(root,preview);create(root);var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/Prefabs/"+id+".prefab");UnityEngine.Object.DestroyImmediate(root);return new DungeonDecorationDefinition{id=id,displayName=name,mount=mount,prefab=prefab,theme=theme,depth=depth,cornerOnly=corner,doorwayFrame=mount==DecorationMount.Door};}
 public static string Build(){Directory.CreateDirectory(Root+"/Materials");Directory.CreateDirectory(Root+"/Prefabs");var importer=(TextureImporter)AssetImporter.GetAtPath(Root+"/Art/MemoryCheckCRT.png");importer.filterMode=FilterMode.Point;importer.mipmapEnabled=false;importer.maxTextureSize=512;importer.textureCompression=TextureImporterCompression.Uncompressed;importer.SaveAndReimport();string atlasPath=Root+"/Art/PlaceholderAtlas.png";if(!File.Exists(atlasPath))File.Copy(AssetDatabase.GetAssetPath(Resources.Load<Texture2D>("placeholder/Atlas de Recursos Cyberpunk Neón")),atlasPath);AssetDatabase.ImportAsset(atlasPath);var atlasImporter=(TextureImporter)AssetImporter.GetAtPath(atlasPath);atlasImporter.filterMode=FilterMode.Point;atlasImporter.mipmapEnabled=false;atlasImporter.textureCompression=TextureImporterCompression.Uncompressed;atlasImporter.SaveAndReimport();var atlas=AssetDatabase.LoadAssetAtPath<Texture2D>(atlasPath);dark=Mat("Carcasa",new Color(.008f,.013f,.04f));metal=Mat("Panel oscuro",new Color(.024f,.036f,.07f));cyan=Mat("Neón cian",new Color(.04f,.80f,.95f));pink=Mat("Neón magenta",new Color(.9f,.025f,.36f));violet=Mat("Neón violeta",new Color(.45f,.04f,.90f));screen=Mat("CRT original",Color.white,AssetDatabase.LoadAssetAtPath<Texture2D>(Root+"/Art/MemoryCheckCRT.png"));vent=Mat("Rejilla del atlas",Color.white,atlas,new Rect(206,35,87,117));control=Mat("Panel del atlas",Color.white,atlas,new Rect(306,35,86,117));sign=Mat("Memory Core del atlas",Color.white,atlas,new Rect(970,350,75,45));glitch=Mat("Corrupción del atlas",Color.white,atlas,new Rect(494,35,92,116));preview=EditorSceneManager.NewPreviewScene();var entries=new List<DungeonDecorationDefinition>();try{
 entries.Add(Save("wall.crt","Monitor CRT de memoria",DecorationMount.Wall,r=>Panel(r,screen),DecorationTheme.Safe));
 entries.Add(Save("wall.vent","Rejilla de ventilación",DecorationMount.Wall,r=>Panel(r,vent,1.25f,1.15f,1.1f)));
 entries.Add(Save("wall.control","Panel técnico retro",DecorationMount.Wall,r=>Panel(r,control,1.35f,.75f,1.65f)));
 entries.Add(Save("wall.sign","Letrero Memory Core",DecorationMount.Wall,r=>Panel(r,sign,2.05f,1.3f,.7f)));
 entries.Add(Save("wall.glitch","Panel de memoria corrupta",DecorationMount.Wall,r=>{Panel(r,glitch,1.35f,1.15f,1.3f);for(int i=0;i<4;i++)Part(r,"Datos corruptos",new Vector3(-.5f+i*.25f,.6f+i*.15f,.3f),new Vector3(.18f,.045f,.08f),violet);},DecorationTheme.Corrupt));
 entries.Add(Save("wall.pipe","Conducto con codos de neón",DecorationMount.Wall,r=>{Part(r,"Columna",new Vector3(-.5f,1.4f,.1f),new Vector3(.18f,2.2f,.20f),metal);Part(r,"Retorno",new Vector3(0,2.45f,.1f),new Vector3(1.15f,.18f,.20f),metal);for(int i=0;i<5;i++)Part(r,"Abrazadera",new Vector3(-.5f,.45f+i*.45f,.2f),new Vector3(.30f,.10f,.08f),cyan);},depth:.25f));
 entries.Add(Save("wall.cable","Cableado de esquina",DecorationMount.Wall,r=>{for(int i=0;i<6;i++){float x=-.6f+i*.24f,y=1.15f+.45f*Mathf.Abs(x);var p=Part(r,"Segmento",new Vector3(x,y,.15f),new Vector3(.28f,.065f,.08f),i%2==0?violet:metal);p.localRotation=Quaternion.Euler(0,0,x<0?-25:25);}Part(r,"Caja de conexiones",new Vector3(.7f,1.7f,.12f),new Vector3(.3f,.5f,.2f),dark);},corner:true));
 entries.Add(Save("wall.window","Ventana de datos holográficos",DecorationMount.Wall,r=>Panel(r,screen,1.6f,2,.75f)));
 entries.Add(Save("floor.circuit","Placa de circuito cian",DecorationMount.Floor,r=>{Part(r,"Placa",new Vector3(0,.005f,0),new Vector3(1.8f,.01f,1.2f),dark);for(int i=0;i<3;i++)Part(r,"Circuito",new Vector3(-.65f+i*.5f,.015f,0),new Vector3(.03f,.01f,.9f),cyan);Part(r,"Bus",new Vector3(0,.017f,.35f),new Vector3(1.5f,.01f,.03f),pink);}));
 entries.Add(Save("floor.signal","Marca digital magenta",DecorationMount.Floor,r=>{for(int i=0;i<3;i++){var p=Part(r,"Marca",new Vector3(-.45f+i*.45f,.015f,0),new Vector3(.14f,.015f,1.15f),pink);p.localRotation=Quaternion.Euler(0,-20,0);}}));
 entries.Add(Save("ceiling.light","Lámpara digital suspendida",DecorationMount.Ceiling,r=>{Part(r,"Soporte",new Vector3(0,-.08f,0),new Vector3(2.3f,.16f,.45f),dark);Part(r,"Luz dibujada",new Vector3(0,-.18f,0),new Vector3(2,.04f,.30f),cyan);}));
 entries.Add(Save("ceiling.duct","Conducto de techo",DecorationMount.Ceiling,r=>{Part(r,"Conducto",new Vector3(0,-.14f,0),new Vector3(.75f,.25f,2.6f),metal);for(int i=0;i<4;i++)Part(r,"Banda",new Vector3(0,-.29f,-.9f+i*.6f),new Vector3(.80f,.045f,.08f),dark);}));
 entries.Add(Save("ceiling.fan","Ventilador digital animado",DecorationMount.Ceiling,r=>{Part(r,"Rejilla",new Vector3(0,-.08f,0),new Vector3(1.35f,.12f,1.35f),dark);var rotor=new GameObject("Aspas");rotor.transform.SetParent(r.transform,false);rotor.transform.localPosition=new Vector3(0,-.19f,0);rotor.transform.localRotation=Quaternion.Euler(90,0,0);for(int i=0;i<4;i++){var p=Part(rotor,"Aspa",new Vector3(.35f,0,0),new Vector3(.60f,.14f,.045f),metal);p.localPosition=Quaternion.Euler(0,0,i*90)*p.localPosition;p.localRotation=Quaternion.Euler(0,0,i*90);}r.AddComponent<DungeonDecorationMotion>().rotor=rotor.transform;}));
 entries.Add(Save("room.server","Rack de servidores",DecorationMount.Room,r=>{Part(r,"Torre",new Vector3(0,1.1f,.3f),new Vector3(1.05f,2.2f,.6f),dark);for(int i=0;i<7;i++){Part(r,"Módulo",new Vector3(0,.22f+i*.28f,.61f),new Vector3(.86f,.22f,.035f),metal);Part(r,"LED",new Vector3(-.32f,.22f+i*.28f,.635f),new Vector3(.12f,.035f,.025f),i%2==0?cyan:pink);}},depth:.65f));
 entries.Add(Save("room.arcade","Máquina arcade de diagnóstico",DecorationMount.Room,r=>{Part(r,"Base",new Vector3(0,.5f,.35f),new Vector3(.95f,1,.65f),dark);Panel(r,screen,1.45f,.72f,.56f);Part(r,"Marquesina",new Vector3(0,1.96f,.35f),new Vector3(1,.2f,.6f),pink);Part(r,"Mandos",new Vector3(0,1.08f,.57f),new Vector3(.85f,.13f,.38f),metal);for(int i=0;i<3;i++)Part(r,"Botón",new Vector3(-.25f+i*.2f,1.16f,.65f),new Vector3(.08f,.04f,.08f),i==0?cyan:pink);},depth:.8f));
 entries.Add(Save("room.generator","Generador de datos",DecorationMount.Room,r=>{Part(r,"Caja",new Vector3(0,.66f,.38f),new Vector3(1.5f,1.3f,.7f),dark);for(int i=0;i<4;i++)Part(r,"Núcleo",new Vector3(-.52f+i*.34f,.68f,.75f),new Vector3(.12f,.8f,.06f),violet);Part(r,"Base",new Vector3(0,.07f,.40f),new Vector3(1.65f,.14f,.8f),metal);},depth:.8f));
 entries.Add(Save("room.column","Columna energética",DecorationMount.Room,r=>{Part(r,"Núcleo",new Vector3(0,1.1f,.4f),new Vector3(.28f,.95f,.28f),cyan,PrimitiveType.Cylinder);foreach(float y in new[]{.12f,2.12f})Part(r,"Tapa",new Vector3(0,y,.4f),new Vector3(.7f,.09f,.7f),dark,PrimitiveType.Cylinder);for(int i=0;i<4;i++){float a=i*Mathf.PI*.5f;Part(r,"Soporte",new Vector3(Mathf.Cos(a)*.27f,1.1f,.4f+Mathf.Sin(a)*.27f),new Vector3(.075f,2,.075f),metal);}},depth:.8f));
 entries.Add(Save("door.frame","Marco de acceso cian",DecorationMount.Door,r=>{foreach(float x in new[]{-1.49f,1.49f}){Part(r,"Marco",new Vector3(x,1.5f,0),new Vector3(.10f,3.05f,.16f),dark);Part(r,"Indicador",new Vector3(x,1.5f,.095f),new Vector3(.035f,2.7f,.025f),cyan);}Part(r,"Dintel",new Vector3(0,3.02f,0),new Vector3(3.15f,.12f,.16f),dark);Part(r,"Acceso",new Vector3(0,3.02f,.10f),new Vector3(2.8f,.035f,.025f),cyan);}));
 var catalog=AssetDatabase.LoadAssetAtPath<DungeonDecorationCatalog>(Root+"/Catalog.asset");if(catalog==null){catalog=ScriptableObject.CreateInstance<DungeonDecorationCatalog>();AssetDatabase.CreateAsset(catalog,Root+"/Catalog.asset");}catalog.entries=entries.ToArray();EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssets();return entries.Count+" prefabs creados, materiales compartidos, sin luces ni colliders";
 }finally{EditorSceneManager.ClosePreviewScene(preview);}}
}
